styles:
/* ---------- related pages ledger ---------- */
.rel{border:1px solid var(--rule);background:#fff;margin-block-start:30px}
.band--tone .rel{background:var(--paper)}
.rel__head{
  display:flex;justify-content:space-between;padding:13px 22px;border-block-end:1px solid var(--rule);
  font-family:var(--data);font-size:10.5px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);
}
.rel a{
  position:relative;display:flex;align-items:center;gap:15px;padding:14px 22px;text-decoration:none;
  border-block-end:1px dotted var(--rule);transition:background .2s ease;
  animation:tibRise .5s ease var(--d,0ms) both;
}
.rel a:last-child{border-block-end:0}
.rel a::before{content:"";position:absolute;inset-block:0;inset-inline-start:0;width:0;background:var(--c,var(--seal));transition:width .25s ease}
.rel a:hover::before{width:3px}
.rel a:hover{background:color-mix(in srgb,var(--c,var(--seal)) 6%,transparent)}
.rel__ic{position:relative;flex:0 0 38px;width:38px;height:38px;border-radius:3px;display:grid;place-items:center;overflow:hidden}
.rel__ic::before{content:"";position:absolute;inset:0;background:var(--c,var(--seal));opacity:.11;transition:opacity .25s ease}
.rel__ic svg{position:relative;width:20px;height:20px;stroke:var(--c,var(--seal));fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;transition:stroke .25s ease}
.rel a:hover .rel__ic::before{opacity:1}
.rel a:hover .rel__ic svg{stroke:#fff}
.rel__n{flex:1;font-size:16.5px}
.rel a:hover .rel__n{color:var(--c,var(--seal))}
.rel__go{font-family:var(--data);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);white-space:nowrap;transition:color .2s ease,transform .25s ease}
.rel a:hover .rel__go{color:var(--c,var(--seal));transform:translateX(4px)}

:root{--display:'Noto Serif Bengali','Noto Serif',serif;--body:'Noto Sans Bengali','Noto Sans',sans-serif;}
html[lang='bn'] body{font-family:var(--body);}
html[lang='bn'] h1,html[lang='bn'] h2,html[lang='bn'] h3,html[lang='bn'] .home-original-strip__n{font-family:var(--display);}
html[lang='ar'] body *,html[lang='bn'] body *{letter-spacing:normal;text-transform:none;}
html[lang='ar'] body{direction:rtl;text-align:right;}
html[lang='ar'] .eyebrow,html[lang='ar'] .meta,html[lang='ar'] .mega__k,html[lang='ar'] .rail-label,html[lang='ar'] .home-original-cred__k,html[lang='ar'] .home-original-cred__head,html[lang='ar'] .home-original-seal,html[lang='ar'] .ticker__i,html[lang='bn'] .eyebrow,html[lang='bn'] .meta,html[lang='bn'] .mega__k,html[lang='bn'] .rail-label,html[lang='bn'] .home-original-cred__k,html[lang='bn'] .home-original-cred__head,html[lang='bn'] .home-original-seal,html[lang='bn'] .ticker__i{letter-spacing:0;text-transform:none;}
html[lang='ar'] .langs,html[lang='ar'] .mark,html[lang='ar'] a[href^='tel:'],html[lang='ar'] a[href^='mailto:'],html[lang='ar'] .home-original-cred__v{direction:ltr;unicode-bidi:isolate;}
html[lang='ar'] .langs{display:flex;}
html[lang='ar'] .mega__all,html[lang='ar'] .home2-text-link,html[lang='ar'] .home2-quick b,html[lang='ar'] .home2-treatment b,html[lang='ar'] .home2-blog-copy b{direction:rtl;}
html[lang='ar'] .home2-process article,html[lang='ar'] .home2-travel-grid>div,html[lang='ar'] .home2-responsibility article{text-align:right;}
html[lang='ar'] .home-original-cred{margin-inline-start:34px;margin-inline-end:0;}
html[lang='ar'] .home-original-cred__row{grid-template-columns:1fr auto;}
html[lang='ar'] .foot__lang,html[lang='ar'] .nap dd{unicode-bidi:plaintext;}
html[lang='bn'] body{line-height:1.72;}
html[lang='bn'] h1,html[lang='bn'] h2,html[lang='bn'] h3{line-height:1.25;}
@media(min-width:1081px){
html[lang='ar'] .nav__item>.mega{inset-inline-start:50%;inset-inline-end:auto;transform:translateX(50%) translateY(-6px);}
html[lang='ar'] .nav__item:hover>.mega,html[lang='ar'] .nav__item:focus-within>.mega{transform:translateX(50%) translateY(0);}
html[lang='ar'] .nav__item:first-child>.mega{inset-inline-start:0;transform:translateX(0) translateY(-6px);}
html[lang='ar'] .nav__item:first-child:hover>.mega,html[lang='ar'] .nav__item:first-child:focus-within>.mega{transform:translateX(0) translateY(0);}
}
@media(max-width:940px){html[lang='ar'] .home-original-cred{margin-inline:18px;}}
